"""Self-contained research workspace; no third-party scripts or market data CDN."""
HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><title>量化研究工作台 · 稻草财经</title>
<style>
:root{--bg:#f5f6f8;--panel:#fff;--ink:#182433;--muted:#6f7c8d;--line:#e5eaf0;--accent:#5264db;--soft:#eef1ff;--red:#d44856;--green:#14876c;--radius:16px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}button,input,select{font:inherit}button,a,input,select{outline-offset:4px}button,a{touch-action:manipulation}button{cursor:pointer;border:1px solid var(--line);border-radius:8px;padding:9px 14px;background:var(--panel);color:var(--ink)}button:hover{border-color:var(--accent)}button:disabled{opacity:.45;cursor:default}.primary{background:var(--accent);border-color:var(--accent);color:#fff}a{color:var(--accent);text-decoration:none}header{height:66px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 32px;background:var(--panel);gap:12px}.brand{display:flex;gap:12px;align-items:center}.mark{display:grid;place-items:center;width:30px;height:30px;background:var(--ink);color:var(--panel);border-radius:8px;font-weight:800}.brand b{font-size:15px}.tag{font-size:11px;color:var(--accent);background:var(--soft);border-radius:5px;padding:3px 8px}.workspace{max-width:1500px;margin:auto;padding:28px 32px 48px}.intro{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px;gap:16px}h1{font-size:27px;letter-spacing:-.8px;margin:0 0 5px}h2{font-size:16px;margin:0}h3{font-size:14px;margin:0 0 10px}p{margin:0}.muted{color:var(--muted);font-size:12px}.layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:22px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:22px}.sidebar{display:flex;flex-direction:column;gap:16px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--muted);font-weight:700;margin-bottom:8px}.field{display:block;margin-top:16px;font-size:12px;color:var(--muted)}input,select{display:block;background:var(--bg);color:var(--ink);width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;margin-top:5px;min-width:0}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.formfoot{display:grid;gap:10px;margin-top:20px}.method{border-top:1px solid var(--line);margin-top:18px;padding-top:15px}.steps{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0 0}.steps span{font-size:10px;background:var(--bg);padding:5px 8px;border-radius:5px;color:var(--muted)}.main{display:flex;flex-direction:column;gap:18px;min-width:0}.empty{min-height:350px;display:grid;place-content:center;text-align:center;gap:12px;padding:40px}.empty .orb{margin:auto;width:60px;height:60px;border-radius:18px;background:var(--soft);display:grid;place-content:center;font-size:28px;color:var(--accent)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin:24px 0}.metric small{display:block;color:var(--muted);font-size:11px}.metric strong{font-size:29px;letter-spacing:-1px;display:block;line-height:1.5;font-variant-numeric:tabular-nums}.pos{color:var(--red)}.neg{color:var(--green)}.sectionhead{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.segments{display:flex;background:var(--bg);border-radius:8px;padding:3px;gap:2px}.segments button{font-size:11px;border:0;background:none;padding:5px 10px}.segments button.on{background:var(--panel);color:var(--accent);box-shadow:0 1px 4px #15274410}.chart{width:100%;height:230px;display:block;margin-top:10px}.chart text{fill:var(--muted);font-size:10px}.chart .grid{stroke:var(--line);stroke-dasharray:4 5}.chart .series{stroke:var(--accent);stroke-width:2.5;fill:none}.note{border-left:3px solid var(--accent);padding:9px 12px;background:var(--soft);font-size:12px;border-radius:0 7px 7px 0;color:var(--muted);margin-top:16px}.alert{border:1px solid #e5c982;background:#fffaee;color:#7c641d;padding:12px 16px;border-radius:10px;font-size:12px}.alert.error{border-color:#e4a8ad;background:#fff2f2;color:#a32a35}.progresshead{display:flex;align-items:center;justify-content:space-between}.progressbar{height:5px;border-radius:5px;background:var(--line);overflow:hidden;margin:16px 0}.progressbar i{display:block;height:100%;background:var(--accent);transition:width .4s}.events{font-size:12px;color:var(--muted);list-style:none;padding:0;margin:0;max-height:150px;overflow:auto}.events li{padding:4px 0}.events time{font-variant-numeric:tabular-nums;margin-right:10px;font-size:10px}.tablewrap{overflow:auto;max-width:100%}table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}th{font-weight:500;color:var(--muted)}details summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center}details summary:after{content:'+';font-size:18px;color:var(--muted)}details[open] summary:after{content:'−'}details>div{margin-top:16px}.record{border:0;border-bottom:1px solid var(--line);border-radius:0;padding:12px 0;text-align:left;width:100%;display:block;background:none}.record b{font-size:12px;display:block}.record small{font-size:10px;color:var(--muted)}.record.on b{color:var(--accent)}.history{max-height:280px;overflow:auto;margin-top:8px}.papergrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:20px 0}.papergrid strong{display:block;font-size:20px;font-variant-numeric:tabular-nums}.hidden{display:none!important}.skeleton{height:10px;background:var(--line);border-radius:4px;width:100%;animation:pulse 1.2s ease-in-out infinite}footer{text-align:center;color:var(--muted);font-size:11px;padding:26px 0 0}#toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);max-width:90%;padding:12px 20px;border-radius:10px;background:var(--ink);color:var(--panel);box-shadow:0 6px 25px #0002;z-index:5}#toast:empty{display:none}@keyframes pulse{50%{opacity:.4}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(prefers-color-scheme:dark){:root{--bg:#10151d;--panel:#181f2b;--ink:#e4e9f2;--muted:#8e9aaf;--line:#293241;--accent:#94a1ff;--soft:#252c47}.primary{background:#6474e2;color:white}.alert{background:#292518;border-color:#514526;color:#d8c38c}.alert.error{background:#321e25;border-color:#66303c;color:#f1adb7}}@media(max-width:1000px){.workspace{padding:24px 20px}.layout{grid-template-columns:240px minmax(0,1fr);gap:16px}.panel{padding:18px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.metric strong{font-size:26px}}@media(max-width:700px){header{padding:0 16px;height:58px}.brand b{font-size:13px}.workspace{padding:20px 12px}.intro{display:block}h1{font-size:23px}.intro>.tag{display:inline-block;margin-top:12px}.layout{grid-template-columns:minmax(0,1fr)}.sidebar{display:contents}.sidebar>.panel:first-child{order:0}.main{order:1}.sidebar>.panel:last-child{order:2}.panel{padding:18px 15px;border-radius:12px}.field{margin-top:12px}.dates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.dates .field{min-width:0}.formfoot{grid-template-columns:1fr auto;align-items:center}.metrics{gap:20px 10px}.chart{height:190px}.sectionhead{flex-wrap:wrap}.empty{min-height:260px;padding:24px}.papergrid{gap:10px}.papergrid strong{font-size:17px}.steps span{font-size:10px}header .muted{display:none}}
.mobile-only{display:none}@media(max-width:700px){.mobile-only{display:inline-block;padding:3px 8px;font-size:11px}.has-result #researchForm:not(.expanded){display:none}.chart text{font-size:18px}}
</style></head><body>
<header><a class="brand" href="/"><span class="mark">稻</span><b>稻草财经 <span class="muted">/ Quant Research</span></b></a><nav class="row" aria-label="研究导航"><a href="/api/quant-research/workspace?view=costs">账务核验</a><a href="/api/quant-research/workspace?view=shares">股份档案</a><a href="/ai-fund">策略实验室 ↗</a></nav></header>
<div class="workspace"><div class="intro"><div><div class="eyebrow">RESEARCH → VALIDATION → PAPER</div><h1>让每一笔决策，经得起回放。</h1><p class="muted">历史回测、样本外验证与模拟跟踪，使用同一套执行规则。</p></div><span class="tag">日频研究 · 不连接实盘</span></div>
<div id="auth" class="alert hidden" style="margin-bottom:18px">请先 <a href="/">返回首页登录</a>，再进入研究工作台。登录后可恢复你的实验记录。</div><div id="error" role="alert" class="alert error hidden" style="margin-bottom:18px"></div>
<div class="layout"><aside class="sidebar"><section class="panel"><div class="eyebrow">01 / DEFINE</div><div class="sectionhead"><h2>新建策略实验</h2><button type="button" id="toggleForm" class="mobile-only" aria-expanded="false">实验设置</button></div><form id="researchForm"><label class="field">实验名称<input id="name" maxlength="80" value="A股动量 · 滚动验证" required></label><label class="field">股票代码 <span class="muted">最多 5 只，逗号分隔</span><input id="symbols" placeholder="600519, 000001, 300750" value="600519, 000001, 300750" required></label><label class="field">价格基准<select id="benchmark"><option value="000300">沪深300</option><option value="000905">中证500</option><option value="000852">中证1000</option></select></label><div class="dates"><label class="field">开始日期<input id="start" type="date" required></label><label class="field">结束日期<input id="end" type="date" required></label></div><div class="method"><p class="muted">固定候选：10 / 20 / 40 日动量，0% / 3% 信号阈值。训练选参后冻结，最终 63 日单独留出。</p><div class="steps"><span>① 真实日线</span><span>② 滚动验证</span><span>③ 模拟跟踪</span></div></div><div class="formfoot"><button class="primary" id="run">开始研究 ↗</button><span class="muted">保留成功与失败记录</span></div></form></section><section class="panel"><div class="sectionhead"><div><div class="eyebrow">EXPERIMENT REGISTRY</div><h2>我的实验档案</h2></div><button id="reload" aria-label="刷新实验档案" style="padding:4px 9px">↻</button></div><div id="history" class="history"><p class="muted">登录后查看实验记录</p></div></section></aside>
<main class="main"><section id="progress" class="panel hidden" aria-live="polite"></section><section id="empty" class="panel empty"><div class="orb">↗</div><h2>先验证，再相信。</h2><p class="muted">从左侧创建实验。系统会封存真实行情、登记参数，<br>依次完成训练、滚动样本外与最终留出验证。</p><p class="muted">不补造行情，不隐藏失败，不把回测收益当作盈利承诺。</p></section><div id="result"></div><div id="papers"></div></main></div><footer>研究结果仅供模拟验证。公开数据商业授权、公司行为及特殊交易状态覆盖尚待核验。</footer></div><div id="toast" role="status" aria-live="polite"></div>
<script>
'use strict';const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=()=>{try{return localStorage.getItem('auth_token')||''}catch{return ''}};let generation=0,selectionEpoch=0,selected=null,chartMode='holdout',timer=null,busy=false,paperBusy=new Set(),ownedToken=token();
const pct=v=>v==null?'—':`${v>=0?'+':''}${Number(v).toFixed(2)}%`,cls=v=>v>=0?'pos':'neg',stamp=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
function notify(t){$('toast').textContent=t;setTimeout(()=>{$('toast').textContent=''},4500)}function showError(t){$('error').textContent=t;$('error').classList.toggle('hidden',!t)}
async function api(path,options={}){const t=token(),g=generation;if(!t)throw Error('请先登录后使用研究工作台');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),60000);try{const r=await fetch('/api/quant-research'+path,{...options,headers:{'Content-Type':'application/json','X-DF-Web':['dfw','2vQ9','k7Rm'].join('_'),Authorization:'Bearer '+t},signal:controller.signal,cache:'no-store'});if(g!==generation||t!==token())throw Error('账号已切换，请刷新');if(r.status===401){reset();throw Error('登录已过期，请返回首页重新登录')}if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error(r.status>=500?'服务暂时繁忙，请稍后重试；同一提交不会重复创建实验。':'请求未完成（'+r.status+'），请稍后重试');let d;try{d=await r.json()}catch{throw Error('研究服务响应异常，请稍后重试')}if(g!==generation||t!==token())throw Error('页面或账号已切换，请刷新');if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'请求未通过校验，请检查代码和日期');return d}finally{clearTimeout(timeout)}}
function clearPrivateView(){document.body.classList.remove('has-result');generation++;selectionEpoch++;selected=null;clearTimeout(timer);$('result').innerHTML='';$('papers').innerHTML='';$('history').textContent='请登录后查看';$('progress').innerHTML='';$('progress').classList.add('hidden');$('empty').classList.remove('hidden');$('auth').classList.remove('hidden');$('run').disabled=true}
function reset(){clearPrivateView()}
function chart(rows){if(!rows?.length)return '<p class="muted">尚无可绘制净值</p>';const values=rows.map(r=>r.return_pct??(r.nav/(selected?.request?.capital||1000000)-1)*100),min=Math.min(0,...values),max=Math.max(0,...values),span=max-min||1,w=760,h=180,x=i=>42+i/Math.max(1,rows.length-1)*(w-60),y=v=>12+(max-v)/span*(h-32);return `<svg class="chart" viewBox="0 0 ${w} 215" role="img" aria-label="成本后策略收益率曲线"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--accent)" stop-opacity=".13"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>${[max,(max+min)/2,min].map(v=>`<line class="grid" x1="42" x2="748" y1="${y(v)}" y2="${y(v)}"/><text x="0" y="${y(v)+3}">${v.toFixed(1)}%</text>`).join('')}<path fill="url(#fade)" d="M${x(0)},${h} L${values.map((v,i)=>`${x(i)},${y(v)}`).join(' L')} L${x(values.length-1)},${h} Z"/><polyline class="series" points="${values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>${[0,Math.floor(rows.length/2),rows.length-1].map(i=>`<text x="${x(i)}" y="205" text-anchor="${i===0?'start':i===rows.length-1?'end':'middle'}">${esc(rows[i].date)}</text>`).join('')}<title>${esc(rows[0].date)} 至 ${esc(rows.at(-1).date)}，期末 ${pct(values.at(-1))}</title></svg>`}
function metric(label,value,sub=''){return `<div class="metric"><small>${label}</small><strong class="${cls(value)}">${pct(value)}</strong><small>${sub}</small></div>`}
function render(job){document.body.classList.add('has-result');selected=job;const item=document.querySelector('[data-job="'+job.id+'"] small');if(item)item.textContent=stamp(job.created)+' · '+({running:'运行中',completed:'已完成',failed:'失败已留档',cancelled:'已取消'}[job.status]||job.status);$('empty').classList.add('hidden');const running=job.status==='running';$('progress').classList.toggle('hidden',!running);if(running){$('result').innerHTML='';$('progress').innerHTML=`<div class="progresshead"><div><div class="eyebrow">02 / VALIDATE</div><h2>${esc(job.stage)}</h2></div><button data-cancel="${esc(job.id)}">取消实验</button></div><div class="progressbar"><i style="width:${Number(job.progress)||0}%"></i></div><ul class="events">${(job.events||[]).slice(-5).map(x=>`<li><time>${esc(new Date(x.at).toLocaleTimeString('zh-CN'))}</time>${esc(x.stage)}</li>`).join('')}</ul>`;return}if(job.status!=='completed'){$('result').innerHTML=`<section class="panel"><div class="eyebrow">EXPERIMENT / ${esc(job.status)}</div><h2>${esc(job.stage)}</h2><p class="muted" style="margin-top:12px">实验记录已保存。修改条件后可重新提交。</p></section>`;return}
const r=job.result,m=chartMode==='holdout'?r.holdout.metrics:r.oos,curve=chartMode==='holdout'?r.holdout.curve:r.oos.curve,gate=r.gate,q=job.quality;const rows=r.folds.map((f,i)=>`<tr><td>窗口 ${i+1}</td><td>${esc(f.train_end)}</td><td>${esc(f.test_start)} → ${esc(f.test_end)}</td><td>${f.parameters.lookback}日 / ${pct(f.parameters.threshold*100)}</td><td class="${cls(f.metrics.return_pct)}">${pct(f.metrics.return_pct)}</td><td>${pct(f.metrics.max_drawdown_pct)}</td><td>${pct(f.metrics.excess_pct)}</td></tr>`).join('');$('result').innerHTML=`<section class="panel"><div class="sectionhead"><div><div class="eyebrow">02 / VALIDATION RESULT</div><h2>${esc(job.request.name)}</h2><p class="muted">${job.request.replay_of?'冻结数据复核一致 · ':''}${esc(job.id.slice(0,8))} · ${stamp(job.created)} · ${q.common_sessions} 个共同交易日<br>实际覆盖 ${esc(q.first)} → ${esc(q.last)}</p></div><div class="segments"><button data-chart="holdout" class="${chartMode==='holdout'?'on':''}">最终留出</button><button data-chart="oos" class="${chartMode==='oos'?'on':''}">滚动样本外</button></div></div><div class="metrics">${metric('成本后收益率',m.return_pct,chartMode==='holdout'?'独立 63 日留出集':'跨窗口连续模拟本金')}${metric('最大回撤',m.max_drawdown_pct,'日收盘净值口径')}${metric('相对价格基准',m.excess_pct,'未含现金分红')}${metric('价格基准收益',m.benchmark_pct,'同区间开盘至末日收盘')}</div>${chart(curve)}<div class="note">${job.kernel_current===false?'执行协议已升级，请新建实验；原记录保留。':gate.passed?'已通过本次研究门槛，可开启冻结参数的模拟跟踪。':'研究门槛未通过：'+gate.reasons.map(esc).join('；')}<br>${r.oos.risk_paused?'样本外账户触发风险暂停，后续空仓；没有为改善回测而自动解除。':''}<br>该门槛不代表策略盈利能力已获证明，也不代表行情商用授权已确认。</div><div class="row" style="margin-top:18px"><button class="primary" data-promote="${esc(job.id)}" ${gate.passed&&job.kernel_current!==false?'':'disabled'}>开启模拟跟踪 →</button><button data-export="${esc(job.id)}">导出实验记录</button><button data-replay="${esc(job.id)}" ${job.kernel_current===false?'disabled':''}>冻结数据复核</button><span class="muted">冻结 ${r.parameters.lookback} 日 / ${pct(r.parameters.threshold*100)}，禁止自动调参</span></div></section><details class="panel" style="margin-top:18px" open><summary><h2>滚动验证 · ${r.folds.length} 个窗口</h2><span class="muted">间隔 5 个交易日 · 末窗按实际长度</span></summary><div class="tablewrap"><table><thead><tr><th>窗口</th><th>训练截止</th><th>样本外区间</th><th>冻结参数</th><th>收益率</th><th>最大回撤</th><th>相对基准</th></tr></thead><tbody>${rows}</tbody></table></div></details><details class="panel" style="margin-top:18px"><summary><h2>数据与执行依据</h2></summary><div><p class="muted">昨日收盘信号，下一交易日开盘模拟执行；滑点 10bps；采用上一日成交量 1% 的参与率上限。单股上限 20%，组合上限 80%，回撤 8% 暂停新增风险。费用为明确的模拟假设。</p><div class="tablewrap"><table><thead><tr><th>代码</th><th>数据源</th><th>日线数</th><th>成交量单位</th></tr></thead><tbody>${Object.entries(q.symbols).map(([s,p])=>`<tr><td>${esc(s)}</td><td>${esc(p.source)}</td><td>${p.bars}</td><td>${esc(p.volume_unit)}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="margin-top:12px">数据指纹 ${esc(r.dataset_digest.slice(0,20))}…<br>执行内核 ${esc(job.kernel.slice(0,20))}…<br>${q.warnings.map(esc).join('<br>')}</p></div></details>`}
async function load(){const loadToken=token(),loadGeneration=generation;if(!token()){reset();return}$('auth').classList.add('hidden');$('run').disabled=busy;const [data,papers]=await Promise.all([api('/experiments'),api('/paper')]);if(loadGeneration!==generation||loadToken!==token())return;$('history').innerHTML=data.items.length?data.items.map(j=>`<button class="record ${selected?.id===j.id?'on':''}" data-job="${esc(j.id)}"><b>${esc(j.request.name)}</b><small>${stamp(j.created)} · ${esc({running:'运行中',completed:'已完成',failed:'失败已留档',cancelled:'已取消'}[j.status]||j.status)}</small></button>`).join(''):'<p class="muted" style="margin-top:12px">还没有实验，创建第一条研究记录。</p>';if(!selected&&data.items.length)await select(data.items[0].id);await renderPapers(papers.items)}
function retryPoll(id,delay=2000){clearTimeout(timer);timer=setTimeout(()=>{if(document.hidden){retryPoll(id,5000);return}select(id).catch(err=>{showError(err.message);if(token()&&selected?.id===id)retryPoll(id,5000)})},delay)}
async function select(id){const epoch=++selectionEpoch,viewGeneration=generation,viewToken=token();clearTimeout(timer);const job=await api('/experiments/'+id);if(epoch!==selectionEpoch||viewGeneration!==generation||viewToken!==token())return;showError('');render(job);try{const pending=JSON.parse(sessionStorage.getItem('quant_research_pending')||'null');if(pending?.job_id===id)sessionStorage.removeItem('quant_research_pending')}catch{}if(job.status==='running')retryPoll(id)}
async function renderPapers(items){$('papers').innerHTML='';for(const item of items){const p=await api('/paper/'+item.id);const last=p.curve.at(-1),ret=last?last.return_pct:0;$('papers').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:18px"><div class="sectionhead"><div><div class="eyebrow">03 / PAPER TRACKING</div><h2>${esc(p.request.name)} <span class="tag">${p.status==='active'?'冻结跟踪中':'已暂停'}</span></h2></div><button data-refresh="${esc(p.id)}" ${p.status==='active'?'':'disabled'}>同步已完成交易日</button></div><div class="papergrid"><div><small class="muted">跟踪收益率</small><strong class="${cls(ret)}">${pct(ret)}</strong></div><div><small class="muted">当前持仓</small><strong>${Object.keys(p.state.positions).length} 只</strong></div><div><small class="muted">模拟成交</small><strong>${p.fills.length} 笔</strong></div></div><p class="muted">${esc(p.start_after)} 之后开始，未回填历史收益。${last?'净值截至 '+esc(last.date):'等待首个完成的交易日。'}<br>${esc(p.last_error||'')}<br>最后核对：${stamp(p.last_check)} · 日频跟踪，共用回测执行内核。</p><div class="tablewrap"><table><thead><tr><th>持仓</th><th>数量</th><th>含费成本</th></tr></thead><tbody>${Object.entries(p.state.positions).map(([s,v])=>`<tr><td>${esc(s)}</td><td>${v.qty}</td><td>${v.cost.toFixed(3)}</td></tr>`).join('')||'<tr><td colspan="3">当前空仓</td></tr>'}</tbody></table></div><details style="margin-top:14px"><summary><span class="muted">查看最近成交与暂停控制</span></summary><div class="tablewrap"><table><thead><tr><th>日期</th><th>代码</th><th>方向</th><th>数量</th><th>费用</th></tr></thead><tbody>${p.fills.slice(-30).reverse().map(f=>`<tr><td>${esc(f.date)}</td><td>${esc(f.symbol)}</td><td>${f.side==='buy'?'买入':'卖出'}</td><td>${f.qty}</td><td>${f.fee.toFixed(2)}</td></tr>`).join('')}</tbody></table></div>${p.status==='active'?`<button data-pause="${esc(p.id)}" style="margin-top:12px">暂停后续模拟跟踪</button>`:''}</details></section>`)}}
$('researchForm').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;$('run').disabled=true;showError('');try{const input={name:$('name').value.trim(),symbols:$('symbols').value.split(/[,，\s]+/).filter(Boolean),benchmark:$('benchmark').value,start_date:$('start').value,end_date:$('end').value};const signature=JSON.stringify(input);let pending;try{pending=JSON.parse(sessionStorage.getItem('quant_research_pending')||'null')}catch{}if(!pending||pending.signature!==signature)pending={signature,id:crypto.randomUUID()};sessionStorage.setItem('quant_research_pending',JSON.stringify(pending));const job=pending.job_id?await api('/experiments/'+pending.job_id):await api('/experiments',{method:'POST',body:JSON.stringify({...input,request_id:pending.id})});pending.job_id=job.id;sessionStorage.setItem('quant_research_pending',JSON.stringify(pending));render(job);$('researchForm').classList.remove('expanded');$('toggleForm').setAttribute('aria-expanded','false');$('toggleForm').textContent='实验设置';await select(job.id);if(window.innerWidth<=700)document.querySelector('main').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});await load();sessionStorage.removeItem('quant_research_pending')}catch(e){if(selected?.status==='running')retryPoll(selected.id,5000);showError(e.name==='AbortError'?'连接等待超时，可再次提交恢复同一实验；不会重复创建。':e.message)}finally{busy=false;$('run').disabled=!token()}});
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;const originalText=b.textContent;try{if(b.dataset.job){await select(b.dataset.job);return}if(b.dataset.chart){chartMode=b.dataset.chart;render(selected);return}if(b.dataset.cancel){await api('/experiments/'+b.dataset.cancel,{method:'DELETE'});await select(b.dataset.cancel);await load();return}if(b.dataset.replay){b.disabled=true;const job=await api('/experiments/'+b.dataset.replay+'/replay',{method:'POST',body:JSON.stringify({request_id:crypto.randomUUID()})});await select(job.id);await load();return}if(b.dataset.export){const d=await api('/experiments/'+b.dataset.export+'/export'),url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='quant-experiment-'+b.dataset.export.slice(0,8)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}const action=b.dataset.promote?'promote':b.dataset.refresh?'refresh':b.dataset.pause?'pause':null;if(action){b.disabled=true;b.textContent='处理中…';const id=b.dataset[action];await api(action==='promote'?'/experiments/'+id+'/paper':'/paper/'+id+'/'+action,{method:'POST'});await load();notify(action==='promote'?'模拟跟踪已开启，参数已冻结':action==='pause'?'已暂停模拟跟踪':'已核对可用日线，重复同步不会重复成交')}}catch(e){showError(e.message);await load().catch(()=>{})}finally{if(b.isConnected){b.disabled=false;if(b.textContent==='处理中…')b.textContent=originalText}}});
$('toggleForm').addEventListener('click',()=>{const expanded=$('researchForm').classList.toggle('expanded');$('toggleForm').setAttribute('aria-expanded',String(expanded));$('toggleForm').textContent=expanded?'收起设置':'实验设置'});$('reload').addEventListener('click',()=>load().catch(e=>showError(e.message)));window.addEventListener('storage',()=>{if(token()!==ownedToken){ownedToken=token();reset();if(ownedToken)load().catch(e=>showError(e.message))}});const today=new Date(),local=new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10);$('end').value=local;$('end').max=local;$('start').value=new Date(today.getTime()-1100*86400000).toISOString().slice(0,10);load().catch(e=>showError(e.message));window.addEventListener('pagehide',()=>clearPrivateView());window.addEventListener('pageshow',event=>{if(!event.persisted)return;const changed=token()!==ownedToken;ownedToken=token();if(changed)reset();else clearPrivateView();if(ownedToken)load().catch(e=>showError(e.message))});
</script></body></html>'''

